            wrapOffset = -keyA % (numKeys - 1) + 1;
            keyA = numKeys - wrapOffset;
        }
        if (keyA == 0 && blendT == 0.0 && frame != 0.0) {
            keyA = anim->keys->count - 1;
        }
        keyB = keyA + 1;
        if (keyB >= anim->keys->count) {
            keyB = 0;
        }
