        poseB = anim->buf0;
    } else if (anim->key1 == keyB) {
        poseB = anim->buf1;
    } else {
        if (keyB < anim->cur) {
            func_8003F2A4(anim);
        }
        while (anim->cur != keyB) {
            func_8003F44C(anim, NULL);
        }
        if (poseA != anim->buf0) {
            anim->key0 = keyB;
            func_8003F44C(anim, anim->buf0);
            poseB = anim->buf0;
        } else {
            anim->key1 = keyB;
            func_8003F44C(anim, anim->buf1);
            poseB = anim->buf1;
        }
