/* Handles parameter changes for an ALLoadFilter: on AL_FILTER_SET_WAVETABLE it binds a wavetable and fills in the ADPCM or raw16 pull handler, loop points and book size; on AL_FILTER_RESET it rewinds the stream state. */ s32
func_800997D0(void *filter, s32 paramID, void *param)
{
    ALLoadFilter *a = (ALLoadFilter *) filter;
    ALFilter *f = (ALFilter *) filter;

    switch (paramID) {
        case (AL_FILTER_SET_WAVETABLE):
            a->table = (ALWaveTable *) param;
            a->memin = a->table->base;
            a->sample = 0;
            switch (a->table->type){
                case (AL_ADPCM_WAVE):




                    f->handler = func_80098FF0;





                    a->table->len = 9  *
                        ((s32) (a->table->len/ 9 ));

                    a->bookSize = 2*a->table->waveInfo.adpcmWave.book->order*
                    a->table->waveInfo.adpcmWave.book->npredictors* 8 ;
                    if (a->table->waveInfo.adpcmWave.loop) {
                        a->loop.start = a->table->waveInfo.adpcmWave.loop->start;
                        a->loop.end = a->table->waveInfo.adpcmWave.loop->end;
