    char *obj = env;
    s32 *input;
    s32 **last;
    s32 (*handler)(s32 *, s32);

    switch (type) {
    case 1:
        *(s32 **)env = value;
        break;
    case 3:
        last = *(s32 **)(env + 0x40);
        if (last != NULL) {
            *last = value;
        } else {
            *(s32 **)(env + 0x3C) = value;
        }
        *(s32 **)(obj + 0x40) = value;
        break;
    case 4:
        obj = *(char **)env;
        *(s32 *)(env + 0x38) = 1;
        *(s32 *)(env + 0x48) = 0;
        *(s16 *)(env + 0x1A) = 1;
        if (obj != NULL) {
            input = (s32 *)obj;
            handler = *(s32 (**)(s32 *, s32))((char *)input + 8);
