#define _SHIFTL(v, s, w) ((u32)(((u32)(v) & ((0x01 << (w)) - 1)) << (s)))
#define A_INIT 0x01
#define A_CONTINUE 0x00
#define A_LEFT 0x02
#define A_RIGHT 0x00
#define A_VOL 0x04
#define A_RATE 0x00
#define A_AUX 0x08
#define A_MAIN 0x00
#define A_SETBUFF 8
#define A_SETVOL 9
#define A_ENVMIXER 3
#define AL_MAIN_L_OUT 0x440
#define AL_MAIN_R_OUT 0x580
#define AL_AUX_L_OUT 0x6C0
#define AL_AUX_R_OUT 0x800
#define EQPOWER_LENGTH 128
#define AL_PLAYING 1

#define aEnvMixer(pkt, f, s) \
    { \
        AcmdU *_a = (AcmdU *)pkt; \
        _a->words.w0 = _SHIFTL(A_ENVMIXER, 24, 8) | _SHIFTL(f, 16, 8); \
        _a->words.w1 = (unsigned int)(s); \
    }
#define aSetBuffer(pkt, f, i, o, c) \
    { \
        AcmdU *_a = (AcmdU *)pkt; \
        _a->words.w0 = (_SHIFTL(A_SETBUFF, 24, 8) | _SHIFTL(f, 16, 8) | _SHIFTL(i, 0, 16)); \
        _a->words.w1 = _SHIFTL(o, 16, 16) | _SHIFTL(c, 0, 16); \
    }
#define aSetVolume(pkt, f, v, t, r) \
    { \
        AcmdU *_a = (AcmdU *)pkt; \
        _a->words.w0 = (_SHIFTL(A_SETVOL, 24, 8) | _SHIFTL(f, 16, 16) | _SHIFTL(v, 0, 16)); \
        _a->words.w1 = _SHIFTL(t, 16, 16) | _SHIFTL(r, 0, 16); \
    }

