{
    s32 found = 0;
    void *voice;

    voice = *(void **)(pool + 0x14);
    if (voice == NULL) {
        voice = *(void **)(pool + 0x4);
    }
    if (voice != NULL) {
        *voiceOut = voice;
        alUnlink(voice);
        alLink(voice, pool + 0xC);
    } else {
        voice = *(void **)(pool + 0xC);
        while (voice != NULL) {
            if (prio >= *(s16 *)(*(u8 **)((u8 *)voice + 8) + 0x16) && *(s32 *)((u8 *)voice + 0xD8) == 0) {
